int CDECL fclose(FILE* file)
{
  int ret;

  if (!MSVCRT_CHECK_PMT(file != NULL)) return EOF;

  _lock_file(file);
  ret = _fclose_nolock(file);
  _unlock_file(file);

  return ret;
}

